export const conditionName=c=>({1:'Low',2:'Moderate',3:'High'}[c]||String(c));
export function transformPosition(p,run,alignment){if(!p)return null;return alignment==='head'?[p[0]-(run.headAnchor?.[0]||0),p[1],p[2]-(run.headAnchor?.[2]||0)]:p.slice();}
export function segments(points,times,start,end,run,alignment){const out=[];let part=[];for(let i=0;i<points.length;i++){const p=points[i];if(times[i]<start||times[i]>end||!p){if(part.length>1)out.push(part);part=[];continue;}part.push(transformPosition(p,run,alignment));}if(part.length>1)out.push(part);return out;}
export function occupancy(runs,keys,start,end,alignment,voxel=.1){const bins=new Map();for(const r of runs){for(const key of keys){const points=r.tracks[key]||[];for(let i=0;i<points.length;i++){if(!points[i]||r.times[i]<start||r.times[i]>end)continue;const p=transformPosition(points[i],r,alignment);const cell=p.map(v=>Math.floor(v/voxel));const id=cell.join(',');if(!bins.has(id))bins.set(id,{position:cell.map(v=>(v+.5)*voxel),seconds:0});bins.get(id).seconds+=1/r.sampleHz;}}}return [...bins.values()];}
export function targetFrequency(runs,metric){const counts=new Map();for(const r of runs){for(const o of r.objects){if(metric==='goal'&&!o.eventsGoalOriginal&&o.outcome!=='goal_attributed_original')continue;if(!counts.has(o.target))counts.set(o.target,new Set());counts.get(o.target).add(r.participant);}}return new Map([...counts].map(([k,v])=>[k,v.size]));}
export function sampleAt(run,key,time){const i=Math.min(run.times.length-1,Math.max(0,Math.round(time*run.sampleHz)));if(time>run.duration+.1)return null;return run.tracks[key]?.[i]||null;}
export function validateRun(r){if(r.schema!=='vr-motion-atlas/1'||typeof r.id!=='string'||!Array.isArray(r.times)||!r.times.length||!r.tracks||!Array.isArray(r.events)||!Array.isArray(r.targets)||!Array.isArray(r.objects))throw Error('Not a compatible vr-motion-atlas/1 run.');for(const key of ['left','right','vl','vr','head']){if(!Array.isArray(r.tracks[key])||r.tracks[key].length!==r.times.length)throw Error('Track lengths differ.');for(const p of r.tracks[key])if(p!==null&&(!Array.isArray(p)||p.length!==3||p.some(v=>!Number.isFinite(v))))throw Error('Invalid coordinate.');}if(r.times.some((v,i)=>!Number.isFinite(v)||(i&&v<r.times[i-1])))throw Error('Times must be finite and ordered.');return r;}
